package com.sgasubtitler.engine;
import com.sgasubtitler.model.*; import java.awt.*; import java.awt.image.*; import java.util.*; import java.util.List;
public final class SubtitleRenderer {
 public BufferedImage render(BufferedImage source,String text,SubtitleStyle style){BufferedImage out=new BufferedImage(source.getWidth(),source.getHeight(),BufferedImage.TYPE_INT_RGB);Graphics2D g=out.createGraphics();g.drawImage(source,0,0,null);paint(g,source.getWidth(),source.getHeight(),text,style,Color.WHITE,Color.BLACK);g.dispose();return out;}
 public BufferedImage mask(int w,int h,String text,SubtitleStyle style){BufferedImage mask=new BufferedImage(w,h,BufferedImage.TYPE_BYTE_GRAY);Graphics2D g=mask.createGraphics();paint(g,w,h,text,style,Color.WHITE,new Color(64,64,64));g.dispose();return mask;}
 private void paint(Graphics2D g,int w,int h,String text,SubtitleStyle style,Color fill,Color outline){g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,RenderingHints.VALUE_TEXT_ANTIALIAS_ON);g.setFont(style.font());FontMetrics fm=g.getFontMetrics();List<String>lines=wrap(text,fm,Math.max(20,w-12));int lineHeight=fm.getHeight(),total=lines.size()*lineHeight;int y=switch(style.position()){case HAUT->6+fm.getAscent();case MILIEU->(h-total)/2+fm.getAscent();case BAS->h-total-6+fm.getAscent();};y=Math.max(fm.getAscent(),Math.min(h-total+fm.getAscent(),y+style.verticalOffset()));for(String line:lines){int x=Math.max(2,(w-fm.stringWidth(line))/2);g.setColor(outline);for(int ox=-style.outline();ox<=style.outline();ox++)for(int oy=-style.outline();oy<=style.outline();oy++)if(ox!=0||oy!=0)g.drawString(line,x+ox,y+oy);g.setColor(fill);g.drawString(line,x,y);y+=lineHeight;}}
 private List<String>wrap(String text,FontMetrics fm,int max){List<String>out=new ArrayList<>();for(String raw:text.split("\\n",-1)){StringBuilder line=new StringBuilder();for(String word:raw.split("\\s+")){String next=line.isEmpty()?word:line+" "+word;if(fm.stringWidth(next)>max&&!line.isEmpty()){out.add(line.toString());line=new StringBuilder(word);}else line=new StringBuilder(next);}out.add(line.toString());}return out;}
}
